// UI-only workflow. Files remain local; no upload, recognition or generation API is invoked.
const videoFlow={step:0,files:[],sample:false,theme:'',style:'',usage:'',duration:'15',ratio:'9:16',note:'',prompt:'',reviewedPrompt:'',error:'',logs:[],sideTab:'任务进度',complete:false};
const videoStages=['准备素材','明确需求','生成要求检查','确认方案','视频交付'];
const videoChoices={theme:[['fuel','油品推广','油品、加油服务与产品展示'],['ticket-percent','站点活动','优惠权益与活动宣传'],['shield-check','安全宣传','安全知识与规范操作'],['users-round','会员营销','会员服务与专属权益'],['building-2','品牌展示','站点形象与团队服务']],style:[['clapperboard','电影质感','有层次的光影与平稳运镜'],['sun','清新明亮','自然光线、整洁清爽'],['briefcase-business','专业可信','稳重表达、清晰可信'],['heart-handshake','温馨亲和','温暖氛围、亲和服务'],['zap','活力动感','明快节奏、年轻表达']],usage:[['smartphone','信息流广告','突出开场，预留文案安全区'],['layout-grid','主页作品','品质呈现与完整叙事'],['radio','直播引流','引出直播主题与活动看点'],['message-circle','朋友圈传播','生活化表达、自然分享'],['monitor','站内播放','信息醒目、适合大屏观看']]};
function videoLog(s){videoFlow.logs.push(s)}
function drawVideo(){render();}
function vSteps(){return `<div class="video-steps">${videoStages.map((s,i)=>`<div class="video-step ${i===videoFlow.step?'active':i<videoFlow.step?'done':''}"><span>${i<videoFlow.step?icon('check'):String(i+1).padStart(2,'0')}</span>${s}</div>`).join('')}</div>`}
function videoWorkspace(){let v=videoFlow;if(tabName==='执行记录')return `<div class="video-work"><div class="video-card"><h3>本次视频任务记录</h3><p class="hint">只记录当前原型会话中的操作，刷新后重置。</p>${v.logs.length?v.logs.map((s,i)=>`<div class="video-log">${String(i+1).padStart(2,'0')} · ${esc(s)}</div>`).join(''):'<p class="empty-note">还没有执行记录。上传素材或载入示例后开始。</p>'}</div></div>`;return `<div class="video-work"><div class="video-intro"><div class="avatar">${icon('clapperboard')}</div><div><h2>把门店素材，变成一条新视频</h2><p>抖音数字员工陪你完成素材整理、创作方向确认与视频交付。</p></div></div>${vSteps()}${v.error?`<div class="video-error" role="alert">${esc(v.error)}</div>`:''}${[vUpload,vIntent,vReview,vConfirm,vDelivery][v.step]()}</div>`}
function vUpload(){let v=videoFlow;return `<div class="video-card"><h3>01 / 准备至少 3 个参考素材</h3><p class="hint">门店外观、员工服务、活动物料等均可，支持图片与视频混合。</p><label class="upload-zone" id="videoDrop" ondragover="event.preventDefault();this.classList.add('dragging')" ondragleave="this.classList.remove('dragging')" ondrop="event.preventDefault();this.classList.remove('dragging');addVideoFiles(event.dataTransfer.files)" tabindex="0" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();document.getElementById('videoFiles').click()}">${icon('cloud-upload')}<strong>点击选择文件，或拖拽素材到这里</strong><small>图片 JPG / PNG / WEBP　·　视频 MP4 / MOV / WEBM</small><input id="videoFiles" type="file" multiple accept=".jpg,.png,.webp,.mp4,.mov,.webm" aria-label="上传参考素材" onchange="addVideoFiles(this.files)"></label><div class="sample-action"><span>素材仅保留在本页，不会上传到服务器</span><button class="link" onclick="loadVideoSample()">${icon('flask-conical')} 用示例素材体验 →</button></div>${v.files.length?`<div class="panel-label"><span>${v.sample?'示例素材清单':'已选择的本地文件'}</span><span>${v.files.length} 个 / 至少 3 个</span></div><div class="file-list">${v.files.map((f,i)=>`<div class="material-row"><div class="material-icon">${icon(f.type==='video'?'film':'image')}</div><div><strong>${esc(f.name)}</strong><small>${esc(f.meta)}${v.sample?' · 示例，非真实上传':''}</small></div><button aria-label="移除素材 ${i+1}" onclick="removeVideoFile(${i})">${icon('x')}</button></div>`).join('')}</div>`:''}<div class="video-info">素材用于参考场景、内容与风格，最终将全新生成视频。上传素材中的原始画面、品牌和人物不会被保证原样保留。</div><div class="video-actions"><small>${v.files.length<3?'还需 '+(3-v.files.length)+' 个素材才能继续':'素材数量与扩展名检查已满足'}</small><button class="primary" onclick="nextVideo()" ${v.files.length<3?'disabled':''}>下一步 · 明确需求 ${icon('arrow-right')}</button></div></div><p class="empty-note">正式接入后将检查素材尺寸、分辨率，并识别内容和场景。当前只校验文件数量与扩展名；大小、分辨率阈值尚未配置。</p>`}
function loadVideoSample(){videoFlow.files=[{name:'门店外观.mp4',type:'video',meta:'12 秒 · 竖屏 9:16'},{name:'员工服务.mp4',type:'video',meta:'8 秒 · 竖屏 9:16'},{name:'会员活动海报.png',type:'image',meta:'1080 × 1920 · 图片'}];videoFlow.sample=true;invalidateVideo();videoFlow.error='';videoLog('载入 3 个示例素材，未执行真实内容识别');drawVideo()}
function addVideoFiles(files){let valid=[],bad=[];for(let f of files){let ext=f.name.split('.').pop().toLowerCase();if(!['jpg','png','webp','mp4','mov','webm'].includes(ext)){bad.push(f.name);continue}if(f.size===0){bad.push(f.name+'（空文件）');continue}valid.push({name:f.name,type:['mp4','mov','webm'].includes(ext)?'video':'image',meta:(f.size/1024/1024).toFixed(2)+' MB · 内容待识别'})}if(valid.length){if(videoFlow.sample)videoFlow.files=[];videoFlow.sample=false;videoFlow.files.push(...valid);invalidateVideo();videoLog('本地选择 '+valid.length+' 个素材，未上传')}videoFlow.error=bad.length?'以下文件无法加入：'+bad.join('、')+'。支持 JPG、PNG、WEBP、MP4、MOV、WEBM，且文件不能为空。':'';drawVideo()}
function removeVideoFile(i){videoFlow.files.splice(i,1);invalidateVideo();videoFlow.error='';drawVideo()}
function invalidateVideo(){videoFlow.reviewedPrompt='';videoFlow.complete=false;videoFlow.prompt=''}
function vIntent(){let v=videoFlow;return `<div class="video-card"><h3>02 / 确认三个创作方向</h3><p class="hint">每组选一个选项，数字员工会据此整理创作方案。</p>${Object.entries(videoChoices).map(([key,choices],j)=>`<div class="choice-group"><h4>${['视频主题','画面风格','使用场景'][j]}<span>单选</span></h4><div class="choice-grid">${choices.map(([ic,label,desc])=>`<button class="choice ${v[key]===label?'selected':''}" aria-pressed="${v[key]===label}" onclick="chooseVideo('${key}','${label}')">${icon(ic)}<div><strong>${label}</strong><small>${desc}</small></div></button>`).join('')}</div></div>`).join('')}<div class="video-form-row"><div class="field"><label for="vDuration">视频时长</label><select id="vDuration" onchange="setVideoOption('duration',this.value)">${['15','20','30'].map(n=>`<option value="${n}" ${v.duration===n?'selected':''}>${n} 秒</option>`).join('')}</select></div><div class="field"><label for="vRatio">画幅</label><select id="vRatio" onchange="setVideoOption('ratio',this.value)"><option ${v.ratio==='9:16'?'selected':''}>9:16</option><option ${v.ratio==='16:9'?'selected':''}>16:9</option></select></div></div><div class="field"><label for="vNote">补充要求 <span style="color:#a2afa6">· 可选</span></label><textarea id="vNote" maxlength="2000" oninput="videoFlow.note=this.value;invalidateVideo()" placeholder="例如：以会员支付场景为主，结尾展示活动时间；需要保留的具体信息请写在这里。">${esc(v.note)}</textarea></div><div class="video-actions"><button class="secondary" onclick="prevVideo()">上一步</button><button class="primary" onclick="nextVideo()" ${!(v.theme&&v.style&&v.usage)?'disabled':''}>下一步 · 检查生成要求 ${icon('arrow-right')}</button></div></div>`}
function chooseVideo(key,value){videoFlow[key]=value;if(key==='usage')videoFlow.ratio=value==='站内播放'?'16:9':'9:16';invalidateVideo();drawVideo()}function setVideoOption(k,val){videoFlow[k]=val;invalidateVideo();renderVideoRight();icons()}
function vReview(){let v=videoFlow;return `<div class="video-card"><h3>03 / 生成要求检查</h3><p class="hint">正式流程会自动识别加油站场景，并应用对应的行业规则；此步骤不可跳过。</p><div class="video-info">${v.sample?'示例场景：加油站 · 使用演示行业规则':'素材场景：待真实识别 · 正式接入后确定适用规则'}</div>${[['scan-eye','场景与素材内容','图片主体、品牌文字；视频关键帧、画幅和时长。','待接入'],['shield-check','行业安全要求','正式检查覆盖危险行为、操作示范、着装与现场安全。','演示规则'],['badge-check','宣传内容与素材授权','核对活动信息、宣传表述，以及音乐、字体和素材授权。','待核实'],['captions','发布场景适配',v.ratio+' 画幅 · '+v.duration+' 秒 · '+v.usage+'，预留必要的文字安全区。','已选参数']].map(([ic,t,d,s])=>`<div class="review-line">${icon(ic)}<div><strong>${t}</strong><p>${d}</p></div><span class="review-status">${s}</span></div>`).join('')}<div class="video-warning">本页仅演示检查流程，不代表素材或最终视频已通过真实安全、广告或版权审查。</div><div class="video-actions"><button class="secondary" onclick="prevVideo()">上一步</button><button class="primary" onclick="nextVideo()">整理创作方案 ${icon('arrow-right')}</button></div></div>`}
function makeVideoPrompt(){let v=videoFlow;return `${v.ratio==='9:16'?'竖屏 9:16':'横屏 16:9'}构图，时长 ${v.duration} 秒，用于${v.usage}。\n以${v.theme}为主题，参考${v.sample?'门店外观、员工服务和会员活动素材':v.files.map(f=>f.name).join('、')}的场景与风格创作全新画面。\n采用${v.style}的视觉风格，从门店环境建立场景，平稳推进至与主题相关的服务细节，最后以清晰的信息画面收束。${v.usage==='信息流广告'?'前三秒突出活动看点，底部预留文案安全区。':v.usage==='站内播放'?'信息清晰醒目，节奏平稳，适合大屏观看。':'保持清晰叙事与自然节奏，预留字幕安全区。'}\n具体价格、权益和活动条件以经确认的活动资料为准，不虚构宣传信息。${v.note?'\n补充要求：'+v.note:''}`}
function vConfirm(){let v=videoFlow;return `<div class="video-card"><h3>04 / 确认创作方案</h3><p class="hint">数字员工已根据你的选择整理方案。可直接修改文字，确认后每次生成 1 条视频。</p><div class="mini-stat"><span>${v.theme}</span><span>${v.style}</span><span>${v.usage}</span><span>${v.duration} 秒 · ${v.ratio}</span></div><label for="vPrompt" style="display:block;font-size:11px;margin:13px 0 8px">创作描述</label><textarea id="vPrompt" style="min-height:235px" maxlength="4000" oninput="editVideoPrompt(this.value)">${esc(v.prompt)}</textarea><div class="prompt-counter"><span id="vPromptCount">${v.prompt.length}</span> / 4000 字符</div><div class="video-info">修改后会重新进入生成前检查。行业约束由生成服务应用，不需要手工填写。本原型不会调用视频生成服务。</div><div class="video-actions"><button class="secondary" onclick="prevVideo()">返回调整需求</button><button class="primary" onclick="confirmVideoPrompt()">${icon('check')} 确认方案 · 演示生成流程</button></div></div>`}
function editVideoPrompt(value){videoFlow.prompt=value;videoFlow.reviewedPrompt='';videoFlow.complete=false;$('#vPromptCount').textContent=value.length}
function confirmVideoPrompt(){let v=videoFlow;if(!v.prompt.trim()){toast('请填写创作描述');return}if(v.prompt.length>4000){toast('创作描述需在 4000 字符以内');return}v.reviewedPrompt=v.prompt;v.step=4;v.complete=false;videoLog('确认当前创作描述，进入生成前检查演示');drawVideo()}
function vDelivery(){let v=videoFlow;return `<div class="video-card"><div class="delivery-state"><div class="delivery-icon">${icon(v.complete?'clipboard-check':'film')}</div><h3>${v.complete?'交付页面已准备好':'方案已确认，等待视频生成服务'}</h3><p>${v.complete?'当前展示交付状态示例，尚无可播放或下载的视频文件。':'正式接入后，将检查当前版本方案，再调用生成服务。'}</p></div><div class="summary-card"><div class="kv"><span>创作方向</span><b>${v.theme} · ${v.style}</b></div><div class="kv"><span>目标规格</span><b>${v.duration} 秒 / ${v.ratio}</b></div><div class="kv"><span>生成数量</span><b>1 条</b></div><div class="kv"><span>视频文件与实际分辨率</span><b>等待服务返回</b></div></div><div class="video-warning">未执行真实素材识别、内容审查或视频生成。正式交付时这里将展示视频播放器、文件信息与下载入口。</div><div class="video-actions"><button class="secondary" onclick="videoFlow.step=3;drawVideo()">返回修改方案</button><button class="primary" onclick="finishVideoDemo()">${icon(v.complete?'download':'arrow-right')} ${v.complete?'下载创作方案':'体验交付状态'}</button></div></div>${v.complete?'<div class="video-card"><h3>发布前核对</h3><p class="hint" style="margin:0">核对最终画面、品牌与文字准确性、活动条件，以及配乐和字体授权，再安排发布。</p></div>':''}`}
function finishVideoDemo(){let v=videoFlow;if(!v.complete){v.complete=true;videoLog('查看交付状态示例；没有生成真实视频');drawVideo();return}let blob=new Blob(['抖音视频创作方案\n\n'+v.prompt+'\n\n备注：UI 演示，尚未生成视频或通过真实审查。'],{type:'text/plain;charset=utf-8'});let url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='抖音视频创作方案.txt';a.click();URL.revokeObjectURL(url);toast('已下载创作方案文本')}
function nextVideo(){let v=videoFlow;v.error='';if(v.step===0&&v.files.length<3){v.error='至少需要 3 个有效素材，请补充后继续。';drawVideo();return}if(v.step===1&&!(v.theme&&v.style&&v.usage)){v.error='请分别选择视频主题、画面风格和使用场景。';drawVideo();return}if(v.step===2){v.prompt=makeVideoPrompt();v.reviewedPrompt='';videoLog('演示生成要求检查，整理创作描述；真实审查待接入')}v.step=Math.min(v.step+1,4);videoLog('进入'+videoStages[v.step]);drawVideo()}
function prevVideo(){videoFlow.step=Math.max(0,videoFlow.step-1);videoFlow.error='';drawVideo()}
function renderVideoRight(){let v=videoFlow;$('#right').innerHTML=`<div class="right-head"><div class="right-title">视频创作空间 <span>抖音数字员工</span></div><div class="tabs">${['任务进度','素材清单','操作记录'].map(t=>`<button class="${v.sideTab===t?'active':''}" onclick="videoFlow.sideTab='${t}';renderVideoRight();icons()">${t}</button>`).join('')}</div></div><div class="panel">${videoSideContent()}</div><div class="panel-actions"><p>本次生成 1 条视频 · 当前为 UI 流程演示</p><button class="secondary" style="margin:0" onclick="navigate('collab')">${icon('messages-square')} 返回全域协作</button></div>`}
function videoSideContent(){let v=videoFlow;if(v.sideTab==='素材清单')return `<h2>参考素材 · ${v.files.length} 个</h2><p class="video-sidenote">${v.sample?'示例清单，不含真实文件。':'文件仅保留在当前页面，尚未上传。'}</p>${v.files.length?v.files.map(f=>`<div class="video-log">${icon(f.type==='video'?'film':'image')} ${esc(f.name)}<br>${esc(f.meta)}</div>`).join(''):'<p class="video-sidenote">等待添加素材。</p>'}`;if(v.sideTab==='操作记录')return `<h2>任务记录</h2>${v.logs.length?v.logs.map(s=>'<div class="video-log">'+esc(s)+'</div>').join(''):'<p class="video-sidenote">完成操作后在这里查看记录。</p>'}`;return `<div class="video-pane-label">DOUYIN / VIDEO STUDIO</div><h2>门店视频创作</h2><div class="intro">先确认创作方向，再让数字员工执行。素材与创作要求始终跟随任务。</div><div class="panel-label"><span>当前阶段</span><span>0${v.step+1} / 05</span></div>${videoStages.map((s,i)=>`<div class="check-row ${i===v.step?'pending':''}" style="${i>v.step?'color:#a6b2aa':''}">${icon(i<v.step?'circle-check':i===v.step?'clock-3':'circle')} ${s}</div>`).join('')}<div class="summary-card"><h4>${icon('folder-open')} 素材准备</h4><div class="kv"><span>参考素材</span><b>${v.files.length} / 至少 3 个</b></div><div class="kv"><span>素材内容识别</span><b>${v.sample?'示例场景':'待接入'}</b></div><div class="kv"><span>使用方式</span><b>参考生成新画面</b></div></div><div class="panel-label">创作方向</div>${[['视频主题',v.theme],['画面风格',v.style],['使用场景',v.usage],['目标规格',v.duration+' 秒 · '+v.ratio]].map(([a,b])=>`<div class="video-side-select"><span>${a}</span><b>${b||'待选择'}</b></div>`).join('')}<div class="video-info">生成前检查不可跳过。正式接入后，修改后的描述也须重新检查。</div><p class="video-sidenote">当前未接入素材识别或视频生成，不会上传文件或扣费。刷新页面将重置本次操作。</p>`}
// Honor a direct preview link without changing the other workspace entry points.
if(new URLSearchParams(location.search).get('view')==='video')navigate('video');
